type Canonical = { id: string; amountCents: bigint; currency: 'EUR' };
const assertNever = (x: never): never => {
  throw new Error(`unknown wire format ${JSON.stringify(x)}`);   // invalid-message path
};
function normalize(wire: Wire): Canonical {
  switch (wire.kind) {
    case 'csv':  return fromCsv(wire.raw);      // narrowed: the xml member is impossible
    case 'xml':  return fromXml(wire.document);
    default:     return assertNever(wire);      // compile error when a format is added
  }
}
